// country: ISO code. category: marketing | utility | authentication. count: messages per month.
return [
  { country: 'NL', category: 'utility', count: 3000 },
  { country: 'NL', category: 'marketing', count: 1000 },
  { country: 'DE', category: 'utility', count: 1500 },
  { country: 'BR', category: 'marketing', count: 2000 },
].map(json => ({ json }));

const csv = $input.first().json.csv;
const rows = csv.trim().split(/\r?\n/).map(l => l.split(','));
const head = rows.shift();
const col = n => head.indexOf(n);
const table = rows.map(r => ({
  market: r[col('market')],
  iso: (r[col('iso_codes')] || '').split(' ').filter(Boolean),
  marketing: Number(r[col('marketing')]),
  utility: Number(r[col('utility')]),
  authentication: Number(r[col('authentication')]),
  effective: r[col('effective_date')],
}));
const fallback = table.find(t => t.market === 'Other');
const out = [];
let total = 0;
for (const item of $('Planned sends (edit me)').all()) {
  const { country, category, count } = item.json;
  // a single-country row wins over a regional row that also lists the code
  const row = table.find(t => t.iso.length === 1 && t.iso[0] === country)
    || table.find(t => t.iso.includes(country)) || fallback;
  const rate = row[category];
  const cost = Math.round(rate * count * 100) / 100;
  total += cost;
  out.push({ country, rate_card: row.market, category, count, eur_per_message: rate, eur_cost: cost, effective_date: row.effective });
}
out.push({ total_eur_per_month: Math.round(total * 100) / 100, note: 'List rates, before volume tiers and free windows' });
return out.map(json => ({ json }));
